/**
 * Build the MCP server.
 *
 * Two steps:
 * 1. Copy the repo-root `custom-elements-manifest.json` (generated by
 *    `pnpm cem` at the repository root) to `packages/mcp/manifest.json`.
 *    The package does NOT scan the component sources on its own — this file
 *    is only a copy, so there is exactly one CEM to keep in sync.
 * 2. Bundle `src/server.js` (and its SDK dependencies) into `dist/server.js`.
 *
 * The package keeps `dependencies` empty to honour the repository's zero
 * runtime dependency rule, so the MCP SDK and zod are bundled at build time
 * and the published entry is a single self-contained file.
 */
import { copyFileSync, existsSync } from 'node:fs';
import { chmod, mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url)); // packages/mcp/
const rootManifest = resolve(root, '../../custom-elements-manifest.json');
const localManifest = resolve(root, 'manifest.json');

if (!existsSync(rootManifest)) {
  console.error(
    `[x-elements-mcp] missing ${rootManifest}. Run "pnpm cem" at the repository root first, ` +
      'then rerun "pnpm --filter @x/mcp build".',
  );
  process.exit(1);
}

copyFileSync(rootManifest, localManifest);
console.log(`[x-elements-mcp] manifest.json <- ${rootManifest}`);

// Imported after the manifest check so a missing root CEM fails fast with a
// clear message instead of a module-resolution error.
const { build } = await import('esbuild');

const dist = new URL('../dist', import.meta.url);
await mkdir(dist, { recursive: true });
await build({
  absWorkingDir: root,
  entryPoints: ['src/server.js'],
  outfile: 'dist/server.js',
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node20',
  banner: { js: '#!/usr/bin/env node' },
  legalComments: 'none',
  logLevel: 'info',
});
await chmod('dist/server.js', 0o755);
